import re

def is_time(t):
    return bool(re.fullmatch(r"\d{1,2}:\d{2}", (t or "").strip()))

cands = [e for e in device.elements()
         if e.get("class_name") == "TextView" and e.get("clickable")
         and (e.get("text") or "").strip()
         and not is_time(e.get("text"))
         and "before" not in e["text"].lower()]
day = str(binding.get("day", ""))
target = next((e for e in cands if re.search(rf"\b{re.escape(day)}\b", e["text"])), None)
if target is None:
    if not cands:
        raise RuntimeError("Start-date field not found on the event form")
    target = cands[0]
device.click(target["index"])

hour = int(binding["hour"])
candidates = [f"{hour:02d}:00", f"{hour}:00", f"{hour % 12 or 12}:00", f"{hour % 12 or 12}:00 PM"[:8]]
idx = None
for t in candidates:
    idx = device.find(text=t, class_name="TextView", clickable=True)
    if idx is not None:
        break
if idx is None:
    raise LookupError(f"Start-time TextView for hour {hour} not found on EventActivity screen")
device.click(idx)

hour = int(binding["hour"])
idx = None
for desc in (f"{hour} hours", f"{hour:02d} hours"):
    idx = device.find(description=desc, clickable=True)
    if idx is not None:
        break
if idx is None:
    raise LookupError(f"Hour {hour} cell not found in time picker")
device.click(index=idx)
